<?php
$outstanding=array_sum(array_map(static fn(array $row): float => max(0,(float)$row['amount_due']),$rows));
$collected=array_sum(array_map(static fn(array $row): float => (float)$row['amount_paid'],$rows));
$billed=array_sum(array_map(static fn(array $row): float => (float)$row['total'],$rows));
$overdue=count(array_filter($rows,static fn(array $row): bool => (float)$row['amount_due']>0&&!in_array($row['status'],['draft','cancelled'],true)&&$row['due_date']<date('Y-m-d')));
$statuses=['draft'=>'Draft','sent'=>'Sent','partially_paid'=>'Partially paid','paid'=>'Paid','overdue'=>'Overdue','cancelled'=>'Cancelled'];
$invoiceProjects=$options['invoice_projects']??$options['projects'];
?>
