<?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="10"><div class="empty-state"><i class="fal fa-file-invoice-dollar"></i><h3>No invoices match</h3><p class="text-muted">Clear the filters or create the first detailed invoice.</p></div></td></tr><?php endif; ?>
</tbody></table></div></div></div></section>

