n></select></div></div><div class="col-md-3"><div class="form-group"><label for="invoice_currency">Currency</label><input class="form-control" id="invoice_currency" name="currency" value="CAD" maxlength="10"></div></div><div class="col-md-3"><div class="form-group"><label for="invoice_po">PO / reference</label><input class="form-control" id="invoice_po" name="purchase_order_number"></div></div></div></div>
