<div class="invoice-form-section"><div class="d-flex justify-content-between align-items-center mb-3"><h3 class="mb-0">Line items</h3><button class="btn btn-sm btn-outline-primary" type="button" data-add-invoice-line><i class="fal fa-plus mr-1"></i>Add line</button></div><div data-invoice-lines><div class="invoice-line"><div><label>Description</label><input class="form-control" name="item_description[]" required placeholder="Service, phase, or deliverable"></div><div><label>Qty</label><input class="form-control" type="number" min="0.01" step="0.01" name="item_quantity[]" value="1" required data-invoice-quantity></div><div><label>Unit price</label><input class="form-control" type="number" min="0.01" step="0.01" name="item_unit_price[]" required data-invoice-price></div><div><label>Line total</label><strong data-invoice-line-total>$0.00</strong></div><button class="btn btn-sm btn-outline-danger" type="button" data-remove-invoice-line title="Remove line"><i class="fal fa-trash-alt"></i></button></div></div><div class="invoice-calculation"><label>Discount <input class="form-control" type="number" min="0" step="0.01" name="discount" value="0" data-invoice-discount></label><label>Tax % <input class="form-control" type="number" min="0" step="0.01" name="tax_percent" value="13" data-invoice-tax></label><div><span>Estimated total</span><strong data-invoice-total>$0.00</strong></div></div></div>
