</div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit"><i class="fal fa-save mr-1"></i>Create invoice</button></div></form></div></div></div>

