<div class="modal fade" id="modal-payment" tabindex="-1" role="dialog" aria-labelledby="payment-title" aria-hidden="true"><div class="modal-dialog" role="document"><div class="modal-content"><form method="post" action="<?= e(url('invoices')) ?>"><div class="modal-header"><div><span class="eyebrow">COLLECTIONS</span><h2 id="payment-title" class="modal-title">Record payment · <span id="payment_invoice"></span></h2></div><button class="close" type="button" data-dismiss="modal"><span>&times;</span></button></div><div class="modal-body"><input type="hidden" name="_token" value="<?= e(\AgencyOS\Csrf::token()) ?>"><input type="hidden" name="action" value="record_payment"><input type="hidden" id="payment_invoice_id" name="invoice_id"><div class="form-group"><label class="required" for="payment_amount">Amount</label><input class="form-control" id="payment_amount" type="number" step="0.01" min="0.01" name="amount" required></div><div class="form-group"><label class="required">Payment date</label><input class="form-control" type="date" name="payment_date" value="<?= e(date('Y-m-d')) ?>" required></div><div class="form-group"><label class="required">Method</label><select class="custom-select" name="method" required><option>Bank transfer</option><option>Credit card</option><option>Cheque</option><option>Cash</option><option>Other</option></select></div><div class="form-group"><label>Reference</label><input class="form-control" name="reference"></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-dismiss="modal">Cancel</button><button class="btn btn-success" type="submit">Record payment</button></div></form></div></div></div>

<script>
document.addEventListener('DOMContentLoaded',function(){var form=document.getElementById('invoice-create-form');if(!form)return;var lines=form.querySelector('[data-invoice-lines]'),template=document.getElementById('invoice-line-template');function money(value){return '$'+Number(value||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});}function calculate(){var subtotal=0;lines.querySelectorAll('.invoice-line').forEach(function(line){var qty=parseFloat(line.querySelector('[data-invoice-quantity]').value)||0,price=parseFloat(line.querySelector('[data-invoice-price]').value)||0,total=qty*price;subtotal+=total;line.querySelector('[data-invoice-line-total]').textContent=money(total);});var discount=parseFloat(form.querySelector('[data-invoice-discount]').value)||0,tax=parseFloat(form.querySelector('[data-invoice-tax]').value)||0,total=Math.max(0,subtotal-discount);total+=total*tax/100;form.querySelector('[data-invoice-total]').textContent=money(total);}form.addEventListener('input',calculate);form.addEventListener('click',function(event){var add=event.target.closest('[data-add-invoice-line]'),remove=event.target.closest('[data-remove-invoice-line]');if(add){lines.appendChild(template.content.cloneNode(true));calculate();}if(remove&&lines.querySelectorAll('.invoice-line').length>1){remove.closest('.invoice-line').remove();calculate();}});calculate();});
</script>
